#include <iostream>
using namespace std;

void addFish(int& bowl, int extra) {
    bowl = bowl + extra;
}

int main() {
    int bowl = 0;
    int extra = 0;
    cin >> bowl >> extra;

    addFish(bowl, extra);
    cout << "碗里现在有 " << bowl << " 条喵" << endl;
    return 0;
}
